function f(t){return(t??60)===30?30:60}function e(t){const n=Math.floor(t/60),r=t%60,o=n<12?"AM":"PM";return`${n%12===0?12:n%12}:${String(r).padStart(2,"0")} ${o}`}function a(t,n){return`${e(t)} – ${e(n)}`}function i(t){return t.start_minute!=null?t.start_minute:t.start_hour>24?t.start_hour:t.start_hour*60}function s(t){return t.end_minute!=null?t.end_minute:t.end_hour>24?t.end_hour:t.end_hour*60}function c(t,n){const r=[...t].sort((o,u)=>o-u);return r.every((o,u)=>u===0||o===r[u-1]+n)}function l(t,n,r){return Math.round(t*n*(r/60))}function h(t,n){return t*n/60}function d(t){return a(i(t),s(t))}function m(t){return e(i(t))}function _(t){if(!t)return null;if(t%60===0){const n=t/60;return n===1?"1 hour":`${n} hours`}return`${t} minutes`}export{m as a,_ as b,e as c,l as d,f as e,d as f,c as i,h as s};
